/**
 * CFB odds-feed team name → catalog abbrev (+ ESPN id). Shared by the Lounge scoreboard and
 * `scripts/cfb-odds-name-audit.mjs` (Node --experimental-strip-types), so keep imports to JSON only.
 */
import cfbTeamEspnByAbbrev from './cfbTeamEspnByAbbrev.json' with { type: 'json' }
import cfbTeamNameAbbrev from './cfbTeamNameAbbrev.json' with { type: 'json' }
import cfbOddsNameEspn from './cfbOddsNameEspn.json' with { type: 'json' }

/**
 * Hand-kept (not regenerated by sync-cfb-team-assets): Odds API names that miss the catalog
 * name map ("Southern Mississippi", "UMass", FCS opponents) → ESPN abbrev + id. Generated catalog wins.
 */
export const CFB_ODDS_ALIASES = cfbOddsNameEspn as Record<string, { abbrev: string; espn: string }>
export const CFB_ESPN_BY_ABBREV: Record<string, string> = {
  ...Object.fromEntries(Object.values(CFB_ODDS_ALIASES).map((v) => [v.abbrev, v.espn])),
  ...(cfbTeamEspnByAbbrev as Record<string, string>),
}
export const CFB_ABBREV_BY_ESPN: Record<string, string> = Object.fromEntries(
  Object.entries(CFB_ESPN_BY_ABBREV).map(([abbrev, espn]) => [String(espn), abbrev]),
)
export const CFB_NAME_ABBREV = cfbTeamNameAbbrev as Record<string, string>

const CFB_ABBREV_ALIASES: Record<string, string> = {
  WSH: 'WASH',
  WAS: 'WASH',
  TAMU: 'TAM',
  'TA&M': 'TAM',
  TEXAM: 'TAM',
  SMISS: 'USM',
  SOMISS: 'USM',
  SOUMISS: 'USM',
  MIOH: 'M-OH',
  MIAOH: 'M-OH',
  'MIAMI-OH': 'M-OH',
  MIAOHIO: 'M-OH',
  GA: 'UGA',
  MISSST: 'MSST',
  MISSSTATE: 'MSST',
  OKLA: 'OU',
  OKL: 'OU',
  PIT: 'PITT',
  NCST: 'NCSU',
  FLAST: 'FSU',
  MIAFL: 'MIA',
  HAWAII: 'HAW',
  WASHST: 'WSU',
  MICHST: 'MSU',
  NW: 'NU',
  NWU: 'NU',
  NWEST: 'NU',
  HOWARD: 'HOW',
  NDSU: 'NDSU',
  NDST: 'NDSU',
  NDSTATE: 'NDSU',
  ROBM: 'RMU',
  ROBMOR: 'RMU',
  RMU: 'RMU',
  COLU: 'COLU',
  CLMB: 'COLU',
  CORN: 'COR',
  COR: 'COR',
}

export function foldCfbName(value: string): string {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

export function resolveCfbCatalogAbbrev(raw: string): string {
  const a = String(raw || '').trim().toUpperCase().replace(/[^A-Z0-9&-]/g, '')
  if (!a) return ''
  if (CFB_ESPN_BY_ABBREV[a]) return a
  const aliased = CFB_ABBREV_ALIASES[a]
  if (aliased && CFB_ESPN_BY_ABBREV[aliased]) return aliased
  return a
}

/** Catalog key must anchor at the start … "West Texas A&M" must not hit "Texas A&M". */
export function cfbNameKeyAnchored(hay: string, key: string, mascot = ''): boolean {
  const h = String(hay || '').trim()
  const k = String(key || '').trim()
  if (!h || !k || k.length < 3) return false
  const prefixes = h.startsWith('the ') ? [k, `the ${k}`] : [k]
  for (const prefix of prefixes) {
    if (h === prefix) return true
    if (!h.startsWith(`${prefix} `)) continue
    const rest = h.slice(prefix.length + 1).trim()
    if (!rest) return true
    const m = String(mascot || '').trim()
    if (m && (rest === m || rest.startsWith(`${m} `))) return true
    return false
  }
  return false
}

/** Words feeds add or drop around the school ("Sam Houston State", "The Citadel", "University of X"). */
const CFB_FILLER_WORDS = new Set(['state', 'university', 'univ', 'the', 'of'])

function stripCfbFiller(folded: string): string {
  return folded.split(' ').filter((t) => t && !CFB_FILLER_WORDS.has(t)).join(' ')
}

/**
 * Filler-stripped "school mascot" → abbrev, built only from catalog keys that end in the mascot
 * (another key for the same team is their school-only prefix). Requiring the mascot keeps
 * "Ohio State Buckeyes" off Ohio (Bobcats) and "Kentucky State Thorobreds" off Kentucky (Wildcats).
 * Stripped forms two teams share are dropped as ambiguous.
 */
const CFB_STRIPPED_MASCOT_KEYS: Map<string, string> = (() => {
  const keysByAbbrev = new Map<string, string[]>()
  for (const [key, abbrev] of Object.entries(CFB_NAME_ABBREV)) {
    const list = keysByAbbrev.get(abbrev) || []
    list.push(key)
    keysByAbbrev.set(abbrev, list)
  }
  const out = new Map<string, string>()
  const ambiguous = new Set<string>()
  for (const [abbrev, keys] of keysByAbbrev) {
    for (const key of keys) {
      const hasMascot = keys.some((school) => school !== key && key.startsWith(`${school} `))
      if (!hasMascot) continue
      const stripped = stripCfbFiller(key)
      if (!stripped || !stripped.includes(' ')) continue
      const prev = out.get(stripped)
      if (prev && prev !== abbrev) ambiguous.add(stripped)
      else out.set(stripped, abbrev)
    }
  }
  for (const s of ambiguous) out.delete(s)
  return out
})()

export function cfbAbbrevFromOddsName(name: string): string {
  const n = foldCfbName(name)
  if (!n) return ''
  if (CFB_NAME_ABBREV[n]) return CFB_NAME_ABBREV[n]
  // Exact only … short aliases ("albany") must not substring-match other schools.
  if (CFB_ODDS_ALIASES[n]) return CFB_ODDS_ALIASES[n].abbrev
  let best = ''
  let bestLen = 0
  for (const [key, abbrev] of Object.entries(CFB_NAME_ABBREV)) {
    if (key.length < 4 || key.length <= bestLen) continue
    // Mascot unknown at this layer … full keys ("texas a m aggies") still anchor; school+"kingsville" fails.
    if (!cfbNameKeyAnchored(n, key, '')) continue
    best = abbrev
    bestLen = key.length
  }
  if (best) return best
  const viaFiller = CFB_STRIPPED_MASCOT_KEYS.get(stripCfbFiller(n))
  if (viaFiller) return viaFiller
  // Do NOT mash the last word to 3 letters into an FBS abbrev … "Hawks" → HAW → Hawaii.
  // Unknown / FCS keep a display stub that is not a catalog hit.
  const guess = resolveCfbCatalogAbbrev((n.split(/\s+/).pop() || n).slice(0, 3).toUpperCase())
  if (guess && CFB_ESPN_BY_ABBREV[guess]) return ''
  return guess
}

/** True when the name resolves to a catalog / alias team (not a display stub). */
export function cfbOddsNameMatched(name: string): boolean {
  const abb = cfbAbbrevFromOddsName(name)
  return Boolean(abb && CFB_ESPN_BY_ABBREV[abb])
}
